head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDSTF30609.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//상용안함 
scwin.fn_SetHeader = function() {
    dts_Edunm.DataID = "/ListedCompany.do?method=listEmptyHeader";
    dts_Edunm.Reset();
    dts_Edunm.insertRow();
};
scwin.fn_SetCode = function() {
    var parentWin = $c.frame.path("../");
    var paramObj = parentWin.gParamObj;
    if (paramObj == undefined) return;
    $c.stf.setObjectValue(txb_ISUR_CD, paramObj.param1);
    $c.stf.setObjectValue(txb_EDU_KIND_CD, paramObj.param2);
    $c.stf.setObjectValue(txb_EDU_KIND_NM, paramObj.param3);
    $c.stf.setObjectValue(txb_EDU_PARTC_ID, paramObj.param4);
    var vEDU_KIND_CD = $c.stf.getObjectValue(txb_EDU_KIND_CD);
    dts_Company.DataID = "/ListedCompany.do?method=getEduName&CHRG_TP_CD=" + vEDU_KIND_CD;
    dts_Company.Reset();
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    var vEDU_ID = $c.stf.getObjectValue(cmb_DISCLS_EDU_CRS_NM);
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var vIEDU_KIND_CD = $c.stf.getObjectValue(txb_EDU_KIND_CD);
    var vIEDU_PARTC_ID = $c.stf.getObjectValue(txb_EDU_PARTC_ID);
    var url = "/ListedCompany.do?method=readEduCompanyPersonInChargeEducationCompletion";
    url += "&EDU_ID=" + vEDU_ID;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Edunm.DataID = encodeURI(url);
    dts_Edunm.Reset();
    $c.stf.setObjectValue(txb_ISUR_CD, vISUR_CD);
    $c.stf.setObjectValue(txb_EDU_KIND_CD, vIEDU_KIND_CD);
    $c.stf.setObjectValue(txb_EDU_PARTC_ID, vIEDU_PARTC_ID);
};
scwin.fn_Save = function() {
    if (confirm("이수처리하시겠습니까?")) {
        trs_Save.Action = "/ListedCompany.do?method=modifyCompanyPersonInChargeEducationCompletion" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Edunm)";
        trs_Save.Post();
    } else {
        return false;
    }
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(txb_EDU_KIND_CD, false);
    $c.stf.showObj(txb_ISUR_CD, false);
    $c.stf.showObj(txb_EDU_ID, false);
    $c.stf.showObj(txb_EDU_PARTC_ID, false);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save); ///('trs_Save.OnFail()');

};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert("이수 처리하였습니다.");
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_COMPLT_DD);
};
scwin.dts_Company_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_DISCLS_EDU_CRS_NM_OnSelChange = function() {
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    //fn_HideDebugCtrls();
    //fn_SetCode();
    //	fn_read_schdl();
    scwin.fn_HideDebugCtrls();
    scwin.fn_SetCode();
    $c.libRoundPanel.PanelToGroupBox(panel_1);
};
